template <class T, bool Depth> struct tex_ret { using type = vec<T, 4>; };
template <class T> struct tex_ret<T, true> { using type = T; };
template <class T, int Access, bool Depth> struct tex_base {
    using R = typename tex_ret<T, Depth>::type;
    template <class... A> R sample(const sampler&, const A&...) const { return R(); }
    template <class... A> float sample_compare(const sampler&, const A&...) const { return 0.0f; }
    template <class... A> R read(const A&...) const { return R(); }
    template <class... A> void write(const A&...) const {}
    template <class... A> vec<T, 4> gather(const sampler&, const A&...) const { return {}; }
    template <class... A> vec<T, 4> gather_compare(const sampler&, const A&...) const { return {}; }
    uint get_width(uint = 0) const { return 0; }
    uint get_height(uint = 0) const { return 0; }
    uint get_depth(uint = 0) const { return 0; }
    uint get_array_size() const { return 0; }
    uint get_num_mip_levels() const { return 0; }
    uint get_num_samples() const { return 0; }
};
#define MSL_TEX(name, depth) template <class T, int Access = 0> struct name : tex_base<T, Access, depth> {};
